// План specs/dashboard.md 3.2 (кейс DB-10). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
// Ключевая проверка: за один и тот же период сумма по техникам = TOTAL SALES, сумма работ = JOBS DONE (виджет Sales & Jobs).
// Сверка — только после ответа обоих RPC за одинаковые p_from/p_to. Падение из-за неназначенной работы
// (её нет ни у одного техника) или >5 техников — это данные компании «test» (ОКРУЖЕНИЕ), не баг.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  PERIOD_LABEL, chooseRange, expectRowsMatchRpc, openDashboardTeam, readSalesTotals, readTeamRows,
  salesWidget, teamWidget, toCents, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance = Sales & Jobs за тот же период (#5814749d)', () => {
  for (const days of [7, 30, 90]) {
    test(`Desktop Team Performance EN: Last ${days} days — sum of technicians equals TOTAL SALES and jobs equal JOBS DONE of Sales & Jobs #5814749d @desktop @prod-safe`, async ({ page }) => {
      const rpc = trackDashboardRpc(page);
      await openDashboardTeam(page, 'en');
      await rpc.teamFor(30); // первая загрузка (30 дней по умолчанию) завершилась

      if (days !== 30) {
        // Одинаковый период в обоих виджетах.
        await chooseRange(page, salesWidget(page, 'en'), 'en', days, 'sales');
        await chooseRange(page, teamWidget(page, 'en'), 'en', days, 'team');
      }
      const team = await rpc.teamFor(days);
      const sales = await rpc.salesFor(team);

      await expect(teamWidget(page, 'en').getByText(PERIOD_LABEL.en(days), { exact: true })).toBeVisible();
      await expect(salesWidget(page, 'en').getByText(PERIOD_LABEL.en(days), { exact: true })).toBeVisible();

      // Данные RPC: Σ total техников = Σ cost графика; Σ job_count = Σ count.
      const teamCents = team.body.reduce((s: number, r: any) => s + toCents(r.total), 0);
      const teamJobs = team.body.reduce((s: number, r: any) => s + Number(r.job_count), 0);
      const salesCents = sales.body.reduce((s: number, d: any) => s + toCents(d.cost), 0);
      const salesJobs = sales.body.reduce((s: number, d: any) => s + Number(d.count), 0);
      expect(teamCents, `RPC: сумма техников = Total Sales за ${team.from}..${team.to}`).toBe(salesCents);
      expect(teamJobs, `RPC: работы техников = Jobs done за ${team.from}..${team.to}`).toBe(salesJobs);

      // Экран: строки отрисованы по ответу RPC, затем сверка с числами Sales & Jobs.
      await expectRowsMatchRpc(page, 'en', team);
      const rows = await readTeamRows(page, 'en');
      const uiCents = rows.reduce((s, r) => s + r.cents, 0);
      const uiJobs = rows.reduce((s, r) => s + r.jobs, 0);
      await expect.poll(() => readSalesTotals(page, 'en'), { message: 'TOTAL SALES / JOBS DONE = сумма строк Team Performance' })
        .toEqual({ cents: uiCents, jobs: uiJobs });
      expect(uiCents).toBe(salesCents);
    });
  }
});
